const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '3:1' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '1' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var y = H * 0.58;
    var x0 = W * 0.12;
    var x1 = W * 0.88;
    var xDiv = x0 + (x1 - x0) * 0.75;

    var line = [
      ['M', x0, y],
      ['L', x1, y]
    ];
    var ticks = [
      ['M', x0, y - 12],
      ['L', x0, y + 12],
      ['M', xDiv, y - 18],
      ['L', xDiv, y + 18],
      ['M', x1, y - 12],
      ['L', x1, y + 12]
    ];

    return {
      schemaVersion: 1,
      sceneId: 'ratio-segment',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'line', commands: line },
        { id: 'ticks', commands: ticks }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'line', fill: '#1f2d3d', stroke: { width: 4 } },
          { type: 'path', pathId: 'ticks', fill: '#1f2d3d', stroke: { width: 3 } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: (x0 + x1) / 2, y: y - 46 }, hAlign: 'center', vAlign: 'bottom', color: '#1f2d3d' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: (x0 + xDiv) / 2, y: y + 28 }, hAlign: 'center', vAlign: 'top', color: '#1f2d3d' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: (xDiv + x1) / 2, y: y + 28 }, hAlign: 'center', vAlign: 'top', color: '#1f2d3d' }
        ]
      }
    };
  }
};
